// Values from the data table codebot_settings
const setting = (k, fallback) => {
  const v = String($input.all().map(i => i.json).find(r => r.key === k)?.value ?? '').trim() || fallback;
  if (!v) throw new Error(`${k} is missing in codebot_settings`);
  return v;
};
const timezone = setting('timezone');
if (!DateTime.now().setZone(timezone).isValid) throw new Error(`timezone in codebot_settings is not a valid IANA time zone: ${timezone}`);
return [{ json: {
  CHAT_ID: setting('telegram_chat_id'),
  TIMEZONE: timezone,
}}];

// Input: { route, update } from CodeBot - Telegram Router. Only text messages from your chat.
const cfg = $('Config').first().json;
const inp = $('From router').first().json;
const msg = (inp.update || inp).message;
if (!msg || String(msg.chat.id) !== String(cfg.CHAT_ID) || !msg.text) return [];
const replyTo = msg.reply_to_message?.text || '';
const m = replyTo.match(/^\[([^\]]+)\]/) || msg.text.match(/^\[([^\]]+)\]/);
return [{ json: { text: msg.text, replyTo, tag: m ? m[1] : null, chatId: msg.chat.id } }];

const tz = $('Config').first().json.TIMEZONE;
const now = DateTime.now().setZone(tz);
const rows = $('Projects').all().map(i => i.json).filter(r => r.key && r.status !== 'Done');
// Read the GitHub response: r0, r1, … = repos (last push), search = open issues and PRs
const gh = $('GitHub').first().json.data || null;
const pushed = {};
for (const [k, v] of Object.entries(gh || {})) if (/^r\d+$/.test(k) && v) pushed[v.nameWithOwner.toLowerCase()] = DateTime.fromISO(v.pushedAt);
const date = s => { const dt = s ? DateTime.fromISO(String(s), { zone: tz }) : null; return dt && dt.isValid ? dt : null; };
const days = dt => dt ? now.diff(dt, 'days').days : null;

const issuesByRepo = {};
for (const i of gh?.search?.nodes || []) {
  const full = i?.repository?.nameWithOwner?.toLowerCase();
  if (!full) continue;
  (issuesByRepo[full] ||= []).push({ number: i.number, title: i.title, pr: i.__typename === 'PullRequest' });
}

const fmt = dt => dt ? dt.toFormat('yyyy-MM-dd') : '-';
const blocks = rows.map(r => {
  const repo = String(r.repo || '').trim().toLowerCase();
  const act = [pushed[repo], date(r.last_checkin)].filter(Boolean).sort((a, b) => b - a)[0] || null;
  const open = issuesByRepo[repo] || [];
  const block = date(r.next_block);
  return [
    `### ${r.name} [${r.key}]`,
    `Status: ${r.status} | Priority: ${r.priority || 'Medium'} | Group: ${r.group || '-'} | Repo: ${repo || 'none'}`,
    `Last activity: ${act ? `${Math.round(days(act))} days ago` : 'unknown'} | Deadline: ${fmt(date(r.deadline))}`,
    `Next planning session in the calendar: ${block && block > now ? block.setLocale('en').toFormat('ccc yyyy-MM-dd HH:mm') : 'none planned'}`,
    `Waiting for: ${r.waiting_for || '-'}${date(r.waiting_since) ? ` (since ${fmt(date(r.waiting_since))})` : ''}`,
    `Next step: ${r.next_step || '-'}`,
    `Description: ${r.description || '-'}`,
    `Open issues/PRs: ${open.length ? open.slice(0, 15).map(i => `#${i.number}${i.pr ? ' (PR)' : ''} ${i.title}`).join('; ') : 'none'}`,
  ].join('\n');
});
if (!gh) blocks.push('Note: GitHub was unreachable just now; issues and latest pushes are missing.');
return [{ json: {
  context: blocks.join('\n\n') || 'No projects found.',
  rows: Object.fromEntries(rows.map(r => [r.key, { status: r.status || '', waiting_for: r.waiting_for || '',
    waiting_since: r.waiting_since || '', next_step: r.next_step || '' }])),
} }];

const out = $input.first().json.output || '';
const m = out.match(/<update>([\s\S]*?)<\/update>/);
let updates = [];
if (m) { try { updates = JSON.parse(m[1]); } catch (e) { updates = []; } }
const reply = out.replace(/<update>[\s\S]*?<\/update>/g, '').trim() || 'Noted.';
return [{ json: { reply: reply.slice(0, 4000), updates: Array.isArray(updates) ? updates : [] } }];

// One item per project to update, with the complete new values of the five fields
const { updates } = $('Parse reply').first().json;
const rows = $('Build context').first().json.rows;
const today = DateTime.now().setZone($('Config').first().json.TIMEZONE).toISODate();
const allowed = ['Active', 'Waiting', 'Paused', 'Someday', 'Done'];

const items = [];
for (const u of updates) {
  const cur = rows[u.key];
  if (!cur) continue;
  const out = { key: u.key, ...cur, last_checkin: today };
  if (u.status && allowed.includes(u.status)) {
    out.status = u.status;
    if (u.status === 'Waiting' && cur.status !== 'Waiting') out.waiting_since = today;
  }
  if ('waiting_for' in u) {
    out.waiting_for = String(u.waiting_for || '').slice(0, 1900);
    if (!u.waiting_for) out.waiting_since = '';
  }
  if (u.next_step) out.next_step = String(u.next_step).slice(0, 1900);
  items.push({ json: out });
}
return items;

// Query GitHub only for the repos in codebot_projects (no account-wide search)
const rows = $('Projects').all().map(i => i.json).filter(r => r.key);
const repos = [...new Set(rows.map(r => String(r.repo || '').trim()).filter(r => /^[\w.-]+\/[\w.-]+$/.test(r)))];
if (!repos.length) return [{ json: { query: 'query { viewer { login } }', repos } }];
const repoParts = repos.map((r, i) => {
  const [o, n] = r.split('/');
  return `  r${i}: repository(owner: "${o}", name: "${n}") { nameWithOwner pushedAt }`;
});
const q = `is:open archived:false ${repos.map(r => 'repo:' + r).join(' ')}`;
const query = `query {
${repoParts.join('\n')}
  search(type: ISSUE, first: 100, query: "${q}") {
    nodes {
      ... on Issue { __typename number title updatedAt repository { nameWithOwner } }
      ... on PullRequest { __typename number title url updatedAt repository { nameWithOwner } }
    }
  }
}`;
return [{ json: { query, repos } }];
